using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record StrategyDraftParameter(string Name,string Value);public sealed record StrategyDraft(string DraftFingerprint,string StrategyId,string SourceFingerprint,IReadOnlyList<StrategyDraftParameter> Parameters,bool ResearchOnly,bool CanSubmitOrders);public static class StrategyDraftRules{public static StrategyDraft Create(string strategyId,string sourceFingerprint,IEnumerable<StrategyDraftParameter> parameters){if(string.IsNullOrWhiteSpace(strategyId))throw new ArgumentException("Strategy id is required.",nameof(strategyId));if(string.IsNullOrWhiteSpace(sourceFingerprint))throw new ArgumentException("Source fingerprint is required.",nameof(sourceFingerprint));var p=parameters.OrderBy(x=>x.Name,StringComparer.Ordinal).ThenBy(x=>x.Value,StringComparer.Ordinal).ToArray();if(p.Any(x=>string.IsNullOrWhiteSpace(x.Name)||string.IsNullOrWhiteSpace(x.Value)))throw new InvalidOperationException("Strategy parameters require names and values.");if(p.Select(x=>x.Name).Distinct(StringComparer.Ordinal).Count()!=p.Length)throw new InvalidOperationException("Strategy parameter names must be unique.");var text=strategyId+"|"+sourceFingerprint+"|"+string.Join("|",p.Select(x=>x.Name+"="+x.Value));var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,strategyId,sourceFingerprint,p,true,false);}public static void Validate(StrategyDraft value){if(!value.ResearchOnly||value.CanSubmitOrders)throw new InvalidOperationException("Strategy drafts must remain research-only.");if(Create(value.StrategyId,value.SourceFingerprint,value.Parameters)!=value)throw new InvalidOperationException("Strategy draft fingerprint or canonical parameters are invalid.");}}
